import zipfile
with zipfile.ZipFile(build/'unsigned.apk','w') as out:
 with zipfile.ZipFile(build/'resources.apk') as src:
  for n in src.namelist():out.writestr(n,src.read(n))
 out.writestr('classes.dex',(dex/'classes.dex').read_bytes())
